BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
LAT=[['拉丁 per；forare','穿过；钻、刺出孔'],['拉丁 perforare → perforatus','穿透、打孔 → 已被穿透的']]
W=[E('perforate','英 /ˈpɜːfəreɪt/；美 /ˈpɜːrfəreɪt/','打孔；穿透，使形成孔洞','把一张纸打出一排小孔，方便沿线撕开，就是 perforate the paper。重点是表面被打穿，而不只是留下凹痕。','per- 接拉丁 per“穿过”，for- 接 forare“钻、刺”。英语早期有表示“被穿透的”的形容词形式，接拉丁 perforatus；动词也有从较早名词 perforation 逆构的分析。不能只按现代动词→名词解释整个词族的出现顺序。',LAT+[['中古英语相关形容词；perforation 名词','“被穿透的”与“孔、打孔”已出现'],['英语动词 perforate','由拉丁分词词干发展，或从较早名词逆构：把东西打穿']],'它可以说一次穿孔，也可以说成排打孔；对象可以是纸、金属等材料。医学文字里也可能用它说组织被穿破，不过这个动词本身并不说明孔是故意加工的，还是意外造成的。','perforate paper；perforate a metal sheet；a machine that perforates tickets。','pierce 强调刺穿，puncture 常说刺出一个孔；perforate 尤其适合谈穿孔、打孔，也常用于一排或一组孔。它不等于把东西彻底切成两半。',('The machine perforates the paper before the sheets are folded.','机器先给纸打孔，再把纸张折起来。'),('The manufacturer perforates the panels to let air pass through.','制造商在板材上打孔，让空气能够通过。'),sources=['https://www.etymonline.com/word/perforate','https://www.oxfordlearnersdictionaries.com/definition/english/perforate']),E('perforated','英 /ˈpɜːfəreɪtɪd/；美 /ˈpɜːrfəreɪtɪd/','有孔的；打过孔的；被穿破的','一张票沿虚线附近有密密的小孔，撕起来很整齐，那条边就可以叫 a perforated edge。这个词让你注意加工后留下的孔。','现代可看作 perforate 加 -ed 的分词或形容词；早期 perforated 也是这个英语词族的记录形式之一。更早接拉丁 perforare／perforatus，不把它简单安排成晚于所有现代动词用法的新造词。',LAT+[['早期英语 perforate／perforated 相关形式','接“穿透、被穿透”的词干与分词用法'],['现代英语 perforated','作为分词或形容词：已被打孔、带有穿孔']],'它描述状态：孔已经在那里。带孔的烤盘、通风金属板、可撕票据都可以用它；在医学上下文中则可能表示组织出现了穿孔，要靠名词判断是设计的孔还是损伤。','perforated paper；a perforated edge；perforated metal。-ed 在这里读 /ɪd/，不要只读一个 /d/。','porous 强调材料有许多孔隙、可渗透；perforated 更容易让人想到表面被打出或穿出了明确的孔。两种描述有时可以重叠，但观察角度不同。',('The notebook has perforated pages that tear out neatly.','这本笔记本的纸页带有孔线，可以整齐地撕下。'),('A perforated metal cover protects the fan without blocking the airflow.','带孔的金属罩保护着风扇，又不挡住气流。'),sources=['https://www.etymonline.com/word/perforate','https://www.oxfordlearnersdictionaries.com/definition/english/perforate']),E('perforation','英 /ˌpɜːfəˈreɪʃən/；美 /ˌpɜːrfəˈreɪʃən/','孔眼；穿孔；打孔的过程','把注意力从“打孔这个动作”移到纸上留下的一排小孔，常用复数 perforations。说整个形成孔洞的过程，也可以用单数不可数的 perforation。','现代可联系 perforate 与 -ion，但历史上英语名词来自中世纪拉丁 perforatio／perforation-，由拉丁 perforare 的分词词干构成；英语名词记录早于现代动词的明确记录，不是先有英语动词再机械添后缀。',LAT+[['中世纪拉丁 perforatio／perforation-','穿孔、打孔的动作或结果'],['中古英语 perforacioun → 英语 perforation','借入名词；用于孔眼或形成孔洞的过程']],'a perforation 可以是一处穿孔；perforations 常指票据、包装或纸张上的一串孔。说工艺过程时，它又可以不可数。这个词的共同点是“贯穿表面形成孔”，并不自动等于整件东西破坏报废。','tear along the perforations；a line of perforations；perforation of a sheet。','hole 是很宽泛的“洞”；perforation 更强调穿过表面的孔或穿孔过程。foramen 则常命名解剖结构中原本就存在的孔道。',('The ticket separated cleanly along the line of perforations.','票沿着那排孔线整齐地分开了。'),('The technician inspected the sheet for unwanted perforations.','技术人员检查板材上有没有不该出现的穿孔。'),sources=['https://www.etymonline.com/word/perforation','https://www.oxfordlearnersdictionaries.com/definition/english/perforation']),E('foramen','英 /fɒˈreɪmen/；美 /fəˈreɪmən/','孔；尤指骨等结构中的天然孔道','骨头并非到处都是实心的。神经或血管可能需要从一个开口穿过去，解剖书会把这样的孔称为 foramen。','直接借入拉丁 foramen“孔、开口”，来自 forare“钻、刺出孔”与名词构词成分 -men。英语借的是整个拉丁名词，不是英语 for“为了”加 amen。',[['拉丁 forare；名词成分 -men','钻、刺出孔；构成结果或对象名称'],['拉丁 foramen','孔、开口'],['英语 foramen','借入解剖等领域，命名自然存在的孔或开口']],'它常见于解剖名称，关注某个结构的通道或开口。最典型的例子是骨上的孔，但范围并不限于骨，也不能一看到这个词就理解为“新发生的穿孔损伤”。','a foramen in the skull；pass through a foramen。复数常用 foramina，也见 foramens。','foramen 常指结构本来具有的开口；perforation 常说穿破或打孔的过程与结果。前者不自动表示异常，后者也不一定表示病变。',('The model shows a nerve passing through a small foramen.','模型显示一条神经穿过一个小孔。'),('The students identified several foramina on the skull model.','学生们在颅骨模型上辨认出了几个孔。'),sources=['https://www.collinsdictionary.com/dictionary/english/foramen','https://www.merriam-webster.com/dictionary/foramen'])]
names=[x['word'] for x in W];cat=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text()) if x['id']=='C0442');EX={w:'较冷门的古生物、地质名词，当前先保留打孔用语和基础解剖名词。' for w in cat['family'] if w not in names}
ROOT=dict(id='C0442',meaning='钻；刺出孔',core='拉丁 forare 的具体动作是“把东西钻开、刺出孔”。加上 per“穿过”，就形成 perforare“打穿”，留下的孔成为这一族共同的画面。',image='forare 钻出孔 → foramen 开口；per + forare 穿透 → perforate 打孔、perforated 带孔、perforation 孔眼或穿孔。',intro='从票据的孔线和金属板的通风孔学起，再理解解剖书中的 foramen。词源动作相连，现代用途需要分别看。',forms='for-／forat- 接拉丁 forare／foratus；foramen 保留拉丁名词形式。perforation 是独立借入的拉丁名词，不以现代英语 perforate 出现后再加 -ion 来替代历史。',branches=[['打孔、孔的状态与结果','perforate, perforated, perforation'],['结构中的孔道','foramen']],contrasts='这里的 for- 与英语介词 for“为了”不同。foramen 往往是原有结构孔道；perforation 往往强调穿孔或打孔，但两者具体含义仍看上下文。',practice='The machine perforates the paper, leaving a perforated edge with a row of perforations. 用动作、状态、孔眼分别复述这句话。',words=names,exclude=EX)
if __name__=='__main__':
 for kind,data in [('roots',[ROOT]),('words',W)]: (OUT/(kind+'_batch200_vid_241.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2))
